function widestOneGap(n: number): number {
  const s = n.toString(2);
  let last = -1, best = 0;
  for (let i = 0; i < s.length; i++) {
    if (s[i] !== "1") continue;
    if (last >= 0) best = Math.max(best, i - last);
    last = i;
  }
  return best;
}

