function widestOneGap(n: number): number {
  let last = -1, best = 0;
  for (let pos = 0; n > 0; pos++, n >>>= 1) {
    if (n & 1) {
      if (last >= 0) best = Math.max(best, pos - last);
      last = pos;
    }
  }
  return best;
}

